-- Full SCI6 curriculum import from the 2026-2027 lesson overview in Google Drive.
-- Adds all coded lessons, matched Google Slides presentations, linked assignments/resources,
-- skipped status, and dated classroom notes. Re-running is safe and merges by lesson code.

do $$
declare
  primary_teacher uuid;
  sci6_curriculum uuid;
begin
  select id into primary_teacher from auth.users
  where lower(email)='mnelsen@susd.net'
  order by created_at limit 1;

  if primary_teacher is null then
    select id into primary_teacher from auth.users
    where raw_app_meta_data ->> 'e3_role'='teacher'
    order by created_at limit 1;
  end if;

  if primary_teacher is not null then
    insert into public.curricula(owner_user_id,name,grade_level,subject,description,source_document_url,is_template)
    values(
      primary_teacher,
      'SCI6 Science 2026-2027',
      '6',
      'Science',
      'Sixth-grade E3 master curriculum imported from the SCI6 lesson overview.',
      'https://docs.google.com/document/d/1p1gmfajnuVHb0i7XvbnKwOITex69aelzEhAfcOGs3J4/edit',
      true
    )
    on conflict(owner_user_id,name) do update set
      grade_level=excluded.grade_level,
      subject=excluded.subject,
      description=excluded.description,
      source_document_url=excluded.source_document_url,
      is_template=true,
      updated_at=now()
    returning curriculum_id into sci6_curriculum;

    insert into public.curriculum_members(curriculum_id,user_id,role)
    values(sci6_curriculum,primary_teacher,'owner')
    on conflict(curriculum_id,user_id) do update set role='owner';
  end if;
end $$;

