insert into public.lesson_records(curriculum_id,lesson_code,title,unit_name,chapter_name,sort_order,status,estimated_periods,mission_position,presentation_url,guide_url,assignments,notebook_pages,resource_links,lesson_notes)
select target.curriculum_id,incoming.* from target cross join incoming
on conflict(curriculum_id,lesson_code) do update set
  title=excluded.title,
  unit_name=excluded.unit_name,
  chapter_name=excluded.chapter_name,
  sort_order=excluded.sort_order,
  status=excluded.status,
  estimated_periods=excluded.estimated_periods,
  mission_position=excluded.mission_position,
  presentation_url=coalesce(excluded.presentation_url,lesson_records.presentation_url),
  guide_url=coalesce(excluded.guide_url,lesson_records.guide_url),
  assignments=lesson_records.assignments || coalesce((select jsonb_agg(x) from jsonb_array_elements(excluded.assignments) x where not exists(select 1 from jsonb_array_elements(lesson_records.assignments) old where old->>'url'=x->>'url')),'[]'::jsonb),
  notebook_pages=lesson_records.notebook_pages || coalesce((select jsonb_agg(x) from jsonb_array_elements(excluded.notebook_pages) x where not exists(select 1 from jsonb_array_elements(lesson_records.notebook_pages) old where old->>'url'=x->>'url')),'[]'::jsonb),
  resource_links=lesson_records.resource_links || coalesce((select jsonb_agg(x) from jsonb_array_elements(excluded.resource_links) x where not exists(select 1 from jsonb_array_elements(lesson_records.resource_links) old where old=x)),'[]'::jsonb),
  lesson_notes=lesson_records.lesson_notes || coalesce((select jsonb_agg(x) from jsonb_array_elements(excluded.lesson_notes) x where not exists(select 1 from jsonb_array_elements(lesson_records.lesson_notes) old where old=x)),'[]'::jsonb),
  updated_at=now();

notify pgrst,'reload schema';

